def add_file(fid,path,origin,relative):
 lines=path.read_text(encoding='utf-8').splitlines();files[fid]={'origin':origin,'path':relative,'local_path':str(path),'sha256':sha(path),'line_count':len(lines)};return lines
def ref(fid,symbol,start,end):
 key=f'{fid}:{symbol}';lines=files[fid]['line_count'];assert 1<=start<=end<=lines
 path=(SKILL/files[fid]['path']) if files[fid]['origin']=='main Skill' else (DEP/files[fid]['path'])
 index[key]={'file':fid,'symbol':symbol,'start':start,'end':end,'snippet_sha256':hashlib.sha256('\n'.join(path.read_text(encoding='utf-8').splitlines()[start-1:end]).encode()).hexdigest()};return key
